changeSet.sql:
ALTER TABLE app.AuditLogs ADD CorrelationId NVARCHAR(64) NULL;
CREATE INDEX IX_AiUsageRecords_Tenant_Created ON app.AiUsageRecords (TenantId, CreatedAt);

CREATE TABLE app.IdempotencyRecords
(
    Id UNIQUEIDENTIFIER NOT NULL,
    TenantId UNIQUEIDENTIFIER NOT NULL,
    UserId UNIQUEIDENTIFIER NOT NULL,
    Operation NVARCHAR(100) NOT NULL,
    IdempotencyKey NVARCHAR(100) NOT NULL,
    StatusCode INT NOT NULL,
    CreatedAt DATETIME2 NOT NULL,
    CONSTRAINT PK_IdempotencyRecords PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT FK_IdempotencyRecords_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id),
    CONSTRAINT FK_IdempotencyRecords_Users FOREIGN KEY (UserId) REFERENCES app.Users (Id)
);
CREATE UNIQUE INDEX UX_IdempotencyRecords_Key ON app.IdempotencyRecords (TenantId, UserId, Operation, IdempotencyKey);

INSERT INTO app.Permissions (Id, Code, Name, Description, CreatedAt, UpdatedAt)
VALUES ('22222222-2222-4222-8222-222222222054', N'PLATFORM_ADMIN', N'Platform administration', N'Manage workspaces and platform status. SuperAdmin only.', SYSUTCDATETIME(), SYSUTCDATETIME());

INSERT INTO app.RolePermissions (RoleId, PermissionId)
SELECT r.Id, p.Id
FROM app.Roles r
JOIN app.Permissions p ON p.Code = N'PLATFORM_ADMIN'
WHERE r.Name = N'SuperAdmin';
